import { useEffect, useState } from "react";
import { io } from "socket.io-client";
import "./AdminDashboard.css";

const socket = io("http://localhost:5000");

function AdminDashboard() {

  const [queues,setQueues]=useState([]);

  const fetchQueues = async()=>{

    const res =
    await fetch(
      "http://localhost:5000/api/queue/all"
    );

    const data =
    await res.json();

    setQueues(data);

  };



  useEffect(()=>{

    fetchQueues();

    socket.on(
      "queueUpdated",
      fetchQueues
    );

    return()=>{

      socket.off(
        "queueUpdated"
      );

    };

  },[]);



  const confirmOP = async(id)=>{

    await fetch(

      `http://localhost:5000/api/queue/confirm/${id}`,

      {

        method:"PUT"

      }

    );

  };



  const completeOP = async(id)=>{

    await fetch(

      `http://localhost:5000/api/queue/complete/${id}`,

      {

        method:"DELETE"

      }

    );

    setQueues(

      prev=>

      prev.filter(

        q=>

        q._id!==id

      )

    );

  };



return(

<div className="admin-page">

<div className="topbar">

<h1>

HealSync Admin

</h1>

</div>



<div className="stats">

<div className="stat-card">

<h2>

{queues.length}

</h2>

<p>

Total OP

</p>

</div>



<div className="stat-card">

<h2>

{

queues.filter(

q=>

q.status===

"InQueue"

).length

}

</h2>

<p>

Waiting

</p>

</div>

</div>



<div className="patients">

{

queues.map(q=>(

<div

className="patient-card"

key={q._id}

>

<div>

<h3>

{q.patientName}

</h3>

<p>

{q.department}

</p>

</div>



<span

className={`status ${q.status}`}

>

{q.status}

</span>



<div className="actions">

{

q.status===

"Waiting" && (

<button

className="confirm"

onClick={()=>

confirmOP(

q._id

)

}

>

Confirm

</button>

)

}



<button

className="complete"

onClick={()=>

completeOP(

q._id

)

}

>

Complete

</button>

</div>

</div>

))

}

</div>

</div>

);

}

export default AdminDashboard;
